// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListActivity The activity feed, newest first, from stored rows only (Phase 6.5, D7): setup events (a setup created or changing state), structure events (BOS, CHOCH, direction established) and resolved ingestion gaps (recovered by backfill, or confirmed to have no data). Open gaps are not listed. Keyset paginated with an opaque cursor.
	// (GET /activity)
	ListActivity(w http.ResponseWriter, r *http.Request, params ListActivityParams)
	// AuthLogin Generic invalid_credentials for unknown email, wrong password or an unverified account alike (ADR-015). On success, sets the session cookie and returns the user.
	// (POST /auth/login)
	AuthLogin(w http.ResponseWriter, r *http.Request)
	// AuthLogout Revokes the current session and clears the cookie. Idempotent.
	// (POST /auth/logout)
	AuthLogout(w http.ResponseWriter, r *http.Request)
	// AuthLogoutAll Revokes every session belonging to the authenticated user.
	// (POST /auth/logout-all)
	AuthLogoutAll(w http.ResponseWriter, r *http.Request)
	// AuthMe The authenticated user.
	// (GET /auth/me)
	AuthMe(w http.ResponseWriter, r *http.Request)
	// AuthListSessions The authenticated user's own active sessions.
	// (GET /auth/sessions)
	AuthListSessions(w http.ResponseWriter, r *http.Request)
	// AuthRevokeSession Revokes one of the authenticated user's own sessions. A session id that exists but belongs to a different user is 404, not 403 (ADR-015: it must not even confirm that id is real).
	// (DELETE /auth/sessions/{id})
	AuthRevokeSession(w http.ResponseWriter, r *http.Request, id int64)
	// AuthSignupComplete Consumes a signup ticket and creates the account, already verified (ADR-015: "no half accounts") -- the first and only point a users row is created for this flow. terms_accepted_at/ terms_version are copied from the signup start this ticket descends from. On success, sets the session cookie and returns the user, the same as login.
	// (POST /auth/signup/complete)
	AuthSignupComplete(w http.ResponseWriter, r *http.Request)
	// AuthSignupStart Starts or restarts a signup: sends a 6-digit emailed code (ADR-015 "Signup and onboarding"). Always 202 with the identical generic body and equal timing whether the email is new or already registered -- for an existing account this sends a notice instead of a code, and the notice itself is skipped silently (never a 429) if the per-email hourly limit is already spent; a new email within its own 60s resend cooldown gets the same silent 202 with nothing re-sent, so that limit can never disclose that the account exists either. 429 is only ever the per-IP limit. Requires accepted_terms: true.
	// (POST /auth/signup/start)
	AuthSignupStart(w http.ResponseWriter, r *http.Request)
	// AuthSignupVerify Checks a 6-digit code and, if correct, returns a single-use signup ticket valid for 30 minutes (ADR-015). One generic invalid_code for a wrong, expired, unknown or exhausted code -- none of those is distinguished for the caller.
	// (POST /auth/signup/verify)
	AuthSignupVerify(w http.ResponseWriter, r *http.Request)
	// GetEngineStatus What the analysis engine has evaluated, from stored processing cursors only (Phase 6.5, D7): per enabled instrument, the close time of the last candle evaluated, when the worker last advanced it, the newest stored closed candle, and how far the evaluation is behind it. Nothing is estimated. A worker tick that found no new candle writes nothing, so last_evaluated_at is the last time a candle was evaluated, not the last time the worker woke up.
	// (GET /engine/status)
	GetEngineStatus(w http.ResponseWriter, r *http.Request)
	// ListInstruments List every registered instrument -- internal/instruments.Store.ListAllFiltered. Defaults to enabled rows only (web-wiring-polish brief, item 2): a disabled test/fixture row filling a capped page was hiding the real, enabled instruments. The enabled query parameter can widen or narrow that.
	// (GET /instruments)
	ListInstruments(w http.ResponseWriter, r *http.Request, params ListInstrumentsParams)
	// ListInstrumentStats Side-panel figures for up to 50 instruments (real-panel-data brief), every one computed on the server with exact scaled- integer arithmetic from stored current (non-superseded), closed 1-minute candles (internal/marketdata.Store.Stats). Enabled instruments only: an unknown or disabled id is simply omitted from the response, never an error, so the response does not reveal which ids exist. A figure whose input candles do not all exist is null, never zero and never approximated from a nearby candle. Duplicate ids are returned once, in first-seen order.
	// (GET /instruments/stats)
	ListInstrumentStats(w http.ResponseWriter, r *http.Request, params ListInstrumentStatsParams)
	// ListInstrumentCandles Closed candles for one instrument in [from, to), at the requested interval (default 1m, so an existing caller that never sends this parameter is unaffected). 1m is served directly (internal/marketdata.Store.ListClosedInRangeLimited, the same read path cmd/argus-worker's own CandleSource uses); 5m/15m/1h/4h/1d are computed on read from the canonical 1-minute series (internal/marketdata.Aggregate/AggregateRange/WindowsInRange) -- the browser never aggregates (live-chart-pipeline brief rule 4), so history and the live stream's own derived candles cannot disagree. A forming candle's own values can still change, so it is never included at any interval; a window with any missing or still- forming source minute is silently excluded, never guessed or partially filled. from/to are both optional at this schema level so order=desc can mean "the latest N, no range known or needed" (web-wiring-polish brief, item 1) for 1m; above 1m both from and to are required regardless of order (see the handler's own comment on why the open-ended "latest N" shortcut is not built for aggregated intervals). Which intervals this endpoint serves for a given instrument is read entirely from that instrument's own supported_intervals (owner approved 12 November 2026) -- an interval not in that list is a 400, never an asset-class guess. Calendar-aware (session-bounded) windows for forex are not built, which is exactly why a forex instrument's own row does not list anything above 1m today.
	// (GET /instruments/{id}/candles)
	ListInstrumentCandles(w http.ResponseWriter, r *http.Request, id int64, params ListInstrumentCandlesParams)
	// GetInstrumentStructure The stored market structure of one instrument and timeframe over a time window, for the chart layers (Phase 6.2): confirmed swings, structure events (BOS, CHOCH, direction established) and liquidity sweeps, current rows only (a row superseded by a candle correction is never returned). Read only. Bounded: [from, to) at most 31 days, and at most limit rows of each kind, oldest first. When any kind reached its limit, every kind is cut at the same time and next_from says where the next page starts, so pages never overlap and never skip a row. Prices are decimal strings at the instrument's price scale. This is the stored structure, not a setup's evidence: a setup's own swings, sweep and break are in GET /setups/{id}/evidence.
	// (GET /instruments/{id}/structure)
	GetInstrumentStructure(w http.ResponseWriter, r *http.Request, id int64, params GetInstrumentStructureParams)
	// GetDrawings The signed-in user's own drawings on one chart (instrument and timeframe). Nothing stored yet: an empty array at version 0. An unknown or disabled instrument is a 404.
	// (GET /me/drawings)
	GetDrawings(w http.ResponseWriter, r *http.Request, params GetDrawingsParams)
	// UpdateDrawings Replaces the drawings on one chart, with the same version rule as PUT /me/preferences (409 on a stale version). data is an array of drawing objects, each with a string id and kind (the rest is the web app's own drawing shape); at most 1000 drawings, and a body above 256 KB is a 413.
	// (PUT /me/drawings)
	UpdateDrawings(w http.ResponseWriter, r *http.Request, params UpdateDrawingsParams)
	// CompleteOnboarding Records onboarding_completed_at (ADR-015), but only once the authenticated user already has a display name and at least one watchlist item -- 409 onboarding_incomplete otherwise: the request itself is well formed, the account's current state is just not yet eligible.
	// (POST /me/onboarding/complete)
	CompleteOnboarding(w http.ResponseWriter, r *http.Request)
	// GetPreferences The signed-in user's own preferences document (owner decision D1, brief-argus-product-overhaul.md Phase 1): every setting the user has made, stored server-side so it survives a cleared browser and a login on another device. A user with nothing stored yet gets an empty object at version 0. Ownership is the session user only.
	// (GET /me/preferences)
	GetPreferences(w http.ResponseWriter, r *http.Request)
	// UpdatePreferences Replaces the whole preferences document. version must be the version the change was based on (0 for the first write); a stale version is a 409 so two tabs or devices never silently overwrite each other -- the client re-reads, re-applies its own changed keys and retries. The document is schema-validated: an unknown key at any level, a wrong type or an out-of-range value is a 400; a body above 64 KB is a 413.
	// (PUT /me/preferences)
	UpdatePreferences(w http.ResponseWriter, r *http.Request)
	// UpdateProfile Sets the authenticated user's display name.
	// (PUT /me/profile)
	UpdateProfile(w http.ResponseWriter, r *http.Request)
	// Ping Connectivity check for the versioned API surface.
	// (GET /ping)
	Ping(w http.ResponseWriter, r *http.Request)
	// ListSetups List current setups for an instrument (and, optionally, a timeframe) -- internal/setups.Store.ListByInstrument. Read-only historical/resource query per ADR-004; live lifecycle transitions are a separate, still-open WebSocket piece, not this endpoint.
	// (GET /setups)
	ListSetups(w http.ResponseWriter, r *http.Request, params ListSetupsParams)
	// GetSetup A single setup by its own id -- internal/setups.Store.GetByID.
	// (GET /setups/{id})
	GetSetup(w http.ResponseWriter, r *http.Request, id int64)
	// ListSetupEvents A setup's full append-only history, in creation order -- internal/setups.Store.ListEvents. The "Evidence" data a client needs to reconstruct how a setup got where it is (ADR-011).
	// (GET /setups/{id}/events)
	ListSetupEvents(w http.ResponseWriter, r *http.Request, id int64)
	// GetSetupEvidence The evidence chain recorded with the setup's decision (Phase 6.1, D6): the ordered steps of the story -- the swept swing, the sweep, the protected swing, the break the order block was anchored to, the premium or discount of the active range, the structural liquidity, the QMR check, the zone and the plan -- each with its candle open times, prices (decimal strings at the instrument's scale), the spec section and its result. The newest recorded chain (the detected event's, or a later amendment's after a candle correction). recorded is false for every setup created before evidence was recorded; nothing is reconstructed for those.
	// (GET /setups/{id}/evidence)
	GetSetupEvidence(w http.ResponseWriter, r *http.Request, id int64)
	// GetWatchlist The authenticated user's own watchlist, in order (ADR-016 -- watchlists are private).
	// (GET /watchlist)
	GetWatchlist(w http.ResponseWriter, r *http.Request)
	// UpdateWatchlist Replaces the authenticated user's whole watchlist at once, in the given order (ADR-015: enabled instruments, maximum 50).
	// (PUT /watchlist)
	UpdateWatchlist(w http.ResponseWriter, r *http.Request)
	// RemoveWatchlistItem Removes one instrument from the authenticated user's own watchlist (D4, product overhaul brief: item-level endpoints, so two tabs never clobber each other the way a whole-list PUT can). Idempotent: removing an instrument that is not on the list is not an error. Ownership comes only from the session. Returns the remaining list, in order.
	// (DELETE /watchlist/items/{instrument_id})
	RemoveWatchlistItem(w http.ResponseWriter, r *http.Request, instrumentId int64)
}

